// 回溯 + 位元遮罩：rows / cols / boxes 各用 9 位元記錄已使用的數字
// 時間複雜度: 最壞 O(9^空格數)，實際因剪枝很快；空間複雜度: O(1)
function solveSudoku(board) {
    const rows = new Array(9).fill(0), cols = new Array(9).fill(0), boxes = new Array(9).fill(0);
    const empty = [];
    const box = (i, j) => Math.floor(i / 3) * 3 + Math.floor(j / 3);
    for (let i = 0; i < 9; i++) {
        for (let j = 0; j < 9; j++) {
            if (board[i][j] === '.') {
                empty.push([i, j]);
            }
            else {
                const bit = 1 << (Number(board[i][j]) - 1);
                rows[i] |= bit;
                cols[j] |= bit;
                boxes[box(i, j)] |= bit;
            }
        }
    }
    const solve = (k) => {
        if (k === empty.length)
            return true;
        const [i, j] = empty[k], b = box(i, j);
        for (let d = 0; d < 9; d++) {
            const bit = 1 << d;
            if ((rows[i] | cols[j] | boxes[b]) & bit)
                continue; // 這個數字已被使用
            rows[i] |= bit;
            cols[j] |= bit;
            boxes[b] |= bit;
            board[i][j] = String(d + 1);
            if (solve(k + 1))
                return true;
            rows[i] ^= bit;
            cols[j] ^= bit;
            boxes[b] ^= bit; // 還原
        }
        board[i][j] = '.';
        return false;
    };
    solve(0);
}

