class Solution {
public:
    void solveSudoku(vector<vector<char>>& board) {
        vector<unordered_set<char>> rows(9);
        vector<unordered_set<char>> cols(9);
        vector<unordered_set<char>> boxes(9);

        // 預處理
        for (int i = 0; i < 9; i++) {
            for (int j = 0; j < 9; j++) {
                if (board[i][j] != '.') {
                    char num = board[i][j];
                    rows[i].insert(num);
                    cols[j].insert(num);
                    int boxIdx = (i / 3) * 3 + j / 3;
                    boxes[boxIdx].insert(num);
                }
            }
        }

        backtrack(board, 0, rows, cols, boxes);
    }

private:
    bool backtrack(vector<vector<char>>& board, int pos,
                   vector<unordered_set<char>>& rows,
                   vector<unordered_set<char>>& cols,
                   vector<unordered_set<char>>& boxes) {
        if (pos == 81) return true;

        int row = pos / 9;
        int col = pos % 9;

        if (board[row][col] != '.') {
            return backtrack(board, pos + 1, rows, cols, boxes);
        }

        int boxIdx = (row / 3) * 3 + col / 3;

        for (char num = '1'; num <= '9'; num++) {
            if (rows[row].count(num) || 
                cols[col].count(num) || 
                boxes[boxIdx].count(num)) {
                continue;
            }

            board[row][col] = num;
            rows[row].insert(num);
            cols[col].insert(num);
            boxes[boxIdx].insert(num);

            if (backtrack(board, pos + 1, rows, cols, boxes)) {
                return true;
            }

            board[row][col] = '.';
            rows[row].erase(num);
            cols[col].erase(num);
            boxes[boxIdx].erase(num);
        }

        return false;
    }
};

