class Solution {
    public void solveSudoku(char[][] board) {
        Set<Character>[] rows = new HashSet[9];
        Set<Character>[] cols = new HashSet[9];
        Set<Character>[] boxes = new HashSet[9];

        for (int i = 0; i < 9; i++) {
            rows[i] = new HashSet<>();
            cols[i] = new HashSet<>();
            boxes[i] = new HashSet<>();
        }

        // 預處理
        for (int i = 0; i < 9; i++) {
            for (int j = 0; j < 9; j++) {
                if (board[i][j] != '.') {
                    char num = board[i][j];
                    rows[i].add(num);
                    cols[j].add(num);
                    int boxIdx = (i / 3) * 3 + j / 3;
                    boxes[boxIdx].add(num);
                }
            }
        }

        backtrack(board, 0, rows, cols, boxes);
    }

    private boolean backtrack(char[][] board, int pos,
                             Set<Character>[] rows,
                             Set<Character>[] cols,
                             Set<Character>[] boxes) {
        if (pos == 81) return true;

        int row = pos / 9;
        int col = pos % 9;

        if (board[row][col] != '.') {
            return backtrack(board, pos + 1, rows, cols, boxes);
        }

        int boxIdx = (row / 3) * 3 + col / 3;

        for (char num = '1'; num <= '9'; num++) {
            if (rows[row].contains(num) || 
                cols[col].contains(num) || 
                boxes[boxIdx].contains(num)) {
                continue;
            }

            board[row][col] = num;
            rows[row].add(num);
            cols[col].add(num);
            boxes[boxIdx].add(num);

            if (backtrack(board, pos + 1, rows, cols, boxes)) {
                return true;
            }

            board[row][col] = '.';
            rows[row].remove(num);
            cols[col].remove(num);
            boxes[boxIdx].remove(num);
        }

        return false;
    }
}

